"""URL validation: format checks, scheme whitelist, and basic malicious-link heuristics."""
from urllib.parse import urlparse

MAX_URL_LENGTH = 2048
ALLOWED_SCHEMES = {"http", "https"}
# Minimal illustrative blocklist; a production system would use a maintained feed.
BLOCKED_DOMAINS = {"malware.test", "phishing.test", "evil.example"}


class ValidationError(ValueError):
    """Raised when submitted input fails validation."""


def validate_url(url):
    """Validate a long URL: required, bounded length, http(s) scheme, non-blocked host."""
    if not url or not isinstance(url, str):
        raise ValidationError("url is required")
    if len(url) > MAX_URL_LENGTH:
        raise ValidationError("url exceeds maximum length")
    parsed = urlparse(url)
    if parsed.scheme not in ALLOWED_SCHEMES:
        raise ValidationError("url scheme must be http or https")
    if not parsed.netloc:
        raise ValidationError("url must include a host")
    host = (parsed.hostname or "").lower()
    if host in BLOCKED_DOMAINS:
        raise ValidationError("url host is blocked")
    if len(parsed.netloc) > 255:
        raise ValidationError("url host too long")
    return True


def validate_alias(alias):
    """Validate an optional custom alias: 1-32 chars, alphanumeric plus - and _."""
    if alias is None:
        return True
    if not isinstance(alias, str) or not (1 <= len(alias) <= 32):
        raise ValidationError("alias must be 1-32 characters")
    if not all(c.isalnum() or c in "-_" for c in alias):
        raise ValidationError("alias contains invalid characters")
    return True

"""API key management and a simple per-client token-bucket rate limiter."""
import secrets
import threading
import time
from datetime import datetime, timezone


def now_iso():
    return datetime.now(timezone.utc).isoformat()


def create_api_key(db, owner_name):
    """Generate and persist a new API key for a given owner name."""
    key = secrets.token_urlsafe(24)
    created = now_iso()
    db.execute(
        "INSERT INTO api_keys (key, owner_name, created_at, active) VALUES (?, ?, ?, 1)",
        (key, owner_name, created),
    )
    return {"api_key": key, "owner_name": owner_name, "created_at": created}


def verify_api_key(db, key):
    """Return the owner name for an active API key, or None if unknown/inactive."""
    if not key:
        return None
    row = db.query_one("SELECT * FROM api_keys WHERE key = ? AND active = 1", (key,))
    return row["owner_name"] if row else None


class RateLimiter:
    """Token-bucket rate limiter keyed by an arbitrary client identifier (API key or IP)."""

    def __init__(self, capacity=50, refill_rate=20.0):
        self.capacity = capacity
        self.refill_rate = refill_rate
        self._buckets = {}
        self._lock = threading.Lock()

    def allow(self, identifier):
        now = time.monotonic()
        with self._lock:
            tokens, last = self._buckets.get(identifier, (self.capacity, now))
            tokens = min(self.capacity, tokens + (now - last) * self.refill_rate)
            if tokens < 1:
                self._buckets[identifier] = (tokens, now)
                return False
            tokens -= 1
            self._buckets[identifier] = (tokens, now)
            return True

"""Core business logic for URL shortening: creation, resolution, update, delete, stats, bulk.

Short codes are generated by base62-encoding an auto-incrementing SQLite row
id (standing in for a distributed Snowflake-like generator), which guarantees
uniqueness without a collision-retry loop.
"""
import threading
from datetime import datetime, timezone

from .validation import validate_url, validate_alias, ValidationError
from .storage import TTLCache
from .analytics import ClickEvent

ALPHABET = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"


def base62_encode(n):
    if n == 0:
        return ALPHABET[0]
    digits = []
    while n:
        n, rem = divmod(n, 62)
        digits.append(ALPHABET[rem])
    return "".join(reversed(digits))


class ConflictError(Exception):
    """Raised when a requested custom alias is already taken."""


class PermissionDeniedError(Exception):
    """Raised when a caller attempts to modify a URL they do not own."""


class NotFoundError(Exception):
    """Raised when a short code does not exist."""


def now_iso():
    return datetime.now(timezone.utc).isoformat()


class URLShortenerService:
    """Coordinates storage, validation, caching and analytics for URL shortening."""

    def __init__(self, db, analytics_queue, base_url="http://localhost:8080"):
        self.db = db
        self.queue = analytics_queue
        self.base_url = base_url.rstrip("/")
        self.cache = TTLCache(maxsize=20000, ttl=60)
        self._lock = threading.Lock()

    def _generate_unique_code(self):
        """Atomically reserve a new row and derive its base62 short code from the row id."""
        with self._lock:
            cur = self.db.execute(
                "INSERT INTO urls (short_code, long_url, created_at) VALUES (?, ?, ?)",
                ("__pending__", "", now_iso()),
            )
            new_id = cur.lastrowid
            code = base62_encode(new_id)
            self.db.execute("UPDATE urls SET short_code = ? WHERE id = ?", (code, new_id))
            return code, new_id

    def create_url(self, long_url, custom_alias=None, expires_at=None, owner_key=None):
        validate_url(long_url)
        validate_alias(custom_alias)
        created = now_iso()
        if custom_alias:
            existing = self.db.query_one("SELECT 1 FROM urls WHERE short_code = ?", (custom_alias,))
            if existing:
                raise ConflictError("alias already in use")
            self.db.execute(
                "INSERT INTO urls (short_code, long_url, owner_key, custom_alias, created_at, expires_at, active) "
                "VALUES (?, ?, ?, 1, ?, ?, 1)",
                (custom_alias, long_url, owner_key, created, expires_at),
            )
            code = custom_alias
        else:
            code, new_id = self._generate_unique_code()
            self.db.execute(
                "UPDATE urls SET long_url = ?, owner_key = ?, created_at = ?, expires_at = ?, active = 1 "
                "WHERE id = ?",
                (long_url, owner_key, created, expires_at, new_id),
            )
        return {
            "short_code": code,
            "short_url": f"{self.base_url}/{code}",
            "long_url": long_url,
            "expires_at": expires_at,
            "created_at": created,
        }

    def create_bulk(self, urls, owner_key=None):
        results = []
        for item in urls:
            long_url = item.get("long_url") if isinstance(item, dict) else item
            alias = item.get("custom_alias") if isinstance(item, dict) else None
            expires_at = item.get("expires_at") if isinstance(item, dict) else None
            try:
                res = self.create_url(long_url, custom_alias=alias, expires_at=expires_at, owner_key=owner_key)
                results.append({"long_url": long_url, "short_code": res["short_code"], "error": None})
            except (ValidationError, ConflictError) as exc:
                results.append({"long_url": long_url, "short_code": None, "error": str(exc)})
        return results

    def resolve(self, short_code, referrer=None, user_agent=None, ip=None):
        """Resolve a short code to its long URL, recording a click event (non-blocking)."""
        long_url = self.cache.get(short_code)
        if long_url is None:
            row = self.db.query_one(
                "SELECT long_url, active, expires_at FROM urls WHERE short_code = ?", (short_code,)
            )
            if row is None or not row["active"]:
                return None
            if row["expires_at"] and row["expires_at"] < now_iso():
                return None
            long_url = row["long_url"]
            self.cache.set(short_code, long_url)
        self.queue.push(ClickEvent(short_code, now_iso(), referrer, user_agent, ip, None))
        return long_url

    def get_stats(self, short_code):
        url_row = self.db.query_one("SELECT long_url FROM urls WHERE short_code = ?", (short_code,))
        if url_row is None:
            return None
        stats_row = self.db.query_one(
            "SELECT total_clicks, last_click_at FROM url_stats WHERE short_code = ?", (short_code,)
        )
        events = self.db.query(
            "SELECT ts, referrer, user_agent, ip FROM click_events WHERE short_code = ? ORDER BY ts DESC LIMIT 20",
            (short_code,),
        )
        return {
            "short_code": short_code,
            "long_url": url_row["long_url"],
            "total_clicks": stats_row["total_clicks"] if stats_row else 0,
            "last_click_at": stats_row["last_click_at"] if stats_row else None,
            "recent_events": [
                {"ts": e["ts"], "referrer": e["referrer"], "user_agent": e["user_agent"], "ip": e["ip"]}
                for e in events
            ],
        }

    def _get_row(self, short_code):
        return self.db.query_one("SELECT owner_key FROM urls WHERE short_code = ?", (short_code,))

    def update_url(self, short_code, owner_key, long_url=None, expires_at=None):
        row = self._get_row(short_code)
        if row is None:
            raise NotFoundError("short code not found")
        if row["owner_key"] and row["owner_key"] != owner_key:
            raise PermissionDeniedError("not the owner of this url")
        if long_url is not None:
            validate_url(long_url)
            self.db.execute("UPDATE urls SET long_url = ? WHERE short_code = ?", (long_url, short_code))
        if expires_at is not None:
            self.db.execute("UPDATE urls SET expires_at = ? WHERE short_code = ?", (expires_at, short_code))
        self.cache.invalidate(short_code)
        updated_row = self.db.query_one("SELECT long_url, expires_at FROM urls WHERE short_code = ?", (short_code,))
        return {
            "short_code": short_code,
            "long_url": updated_row["long_url"],
            "expires_at": updated_row["expires_at"],
            "updated": True,
        }

    def delete_url(self, short_code, owner_key):
        row = self._get_row(short_code)
        if row is None:
            raise NotFoundError("short code not found")
        if row["owner_key"] and row["owner_key"] != owner_key:
            raise PermissionDeniedError("not the owner of this url")
        self.db.execute("UPDATE urls SET active = 0 WHERE short_code = ?", (short_code,))
        self.cache.invalidate(short_code)
        return {"short_code": short_code, "deleted": True}

"""HTTP API layer: a BaseHTTPRequestHandler that routes requests to the service layer."""
import json
import re
from http.server import BaseHTTPRequestHandler
from urllib.parse import urlparse

from .auth import verify_api_key, create_api_key
from .validation import ValidationError
from .service import ConflictError, PermissionDeniedError, NotFoundError

STATS_RE = re.compile(r"^/api/urls/([A-Za-z0-9_-]+)/stats$")
URL_ITEM_RE = re.compile(r"^/api/urls/([A-Za-z0-9_-]+)$")
SHORT_RE = re.compile(r"^/([A-Za-z0-9_-]+)$")


def make_handler(service, db, rate_limiter):
    """Build a request handler class bound to the given service/db/rate-limiter instances."""

    class Handler(BaseHTTPRequestHandler):
        server_version = "URLShortener/1.0"

        def log_message(self, fmt, *args):
            pass  # keep test/CI output quiet

        def _send_json(self, status, payload):
            body = json.dumps(payload).encode("utf-8")
            self.send_response(status)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def _read_json(self):
            length = int(self.headers.get("Content-Length", 0) or 0)
            if length == 0:
                return {}
            raw = self.rfile.read(length)
            try:
                return json.loads(raw.decode("utf-8"))
            except ValueError:
                raise ValidationError("invalid JSON body")

        def _client_id(self):
            return self.headers.get("X-API-Key") or self.client_address[0]

        def _check_rate_limit(self):
            if not rate_limiter.allow(self._client_id()):
                self._send_json(429, {"error": "rate limit exceeded"})
                return False
            return True

        def _api_key(self):
            return self.headers.get("X-API-Key")

        def do_GET(self):
            if not self._check_rate_limit():
                return
            path = urlparse(self.path).path
            m = STATS_RE.match(path)
            if m:
                self._handle_stats(m.group(1))
                return
            if path.startswith("/api/"):
                self._send_json(404, {"error": "not found"})
                return
            m = SHORT_RE.match(path)
            if m:
                self._handle_redirect(m.group(1))
                return
            self._send_json(404, {"error": "not found"})

        def do_POST(self):
            if not self._check_rate_limit():
                return
            path = urlparse(self.path).path
            try:
                if path == "/api/urls":
                    self._handle_create()
                elif path == "/api/urls/bulk":
                    self._handle_bulk()
                elif path == "/api/keys":
                    self._handle_create_key()
                else:
                    self._send_json(404, {"error": "not found"})
            except ValidationError as exc:
                self._send_json(400, {"error": str(exc)})
            except ConflictError as exc:
                self._send_json(409, {"error": str(exc)})

        def do_PUT(self):
            if not self._check_rate_limit():
                return
            path = urlparse(self.path).path
            m = URL_ITEM_RE.match(path)
            if not m:
                self._send_json(404, {"error": "not found"})
                return
            try:
                self._handle_update(m.group(1))
            except ValidationError as exc:
                self._send_json(400, {"error": str(exc)})
            except PermissionDeniedError as exc:
                self._send_json(403, {"error": str(exc)})
            except NotFoundError as exc:
                self._send_json(404, {"error": str(exc)})

        def do_DELETE(self):
            if not self._check_rate_limit():
                return
            path = urlparse(self.path).path
            m = URL_ITEM_RE.match(path)
            if not m:
                self._send_json(404, {"error": "not found"})
                return
            try:
                self._handle_delete(m.group(1))
            except PermissionDeniedError as exc:
                self._send_json(403, {"error": str(exc)})
            except NotFoundError as exc:
                self._send_json(404, {"error": str(exc)})

        def _handle_create(self):
            body = self._read_json()
            result = service.create_url(
                body.get("long_url"),
                custom_alias=body.get("custom_alias"),
                expires_at=body.get("expires_at"),
                owner_key=self._api_key(),
            )
            self._send_json(201, result)

        def _handle_bulk(self):
            body = self._read_json()
            urls = body.get("urls")
            if not isinstance(urls, list) or not urls:
                self._send_json(400, {"error": "urls must be a non-empty list"})
                return
            results = service.create_bulk(urls, owner_key=self._api_key())
            self._send_json(201, {"results": results})

        def _handle_create_key(self):
            body = self._read_json()
            owner_name = body.get("owner_name")
            if not owner_name:
                self._send_json(400, {"error": "owner_name is required"})
                return
            result = create_api_key(db, owner_name)
            self._send_json(201, result)

        def _handle_redirect(self, code):
            long_url = service.resolve(
                code,
                referrer=self.headers.get("Referer"),
                user_agent=self.headers.get("User-Agent"),
                ip=self.client_address[0],
            )
            if long_url is None:
                self._send_json(404, {"error": "short code not found or expired"})
                return
            self.send_response(302)
            self.send_header("Location", long_url)
            self.send_header("Content-Length", "0")
            self.end_headers()

        def _handle_stats(self, code):
            stats = service.get_stats(code)
            if stats is None:
                self._send_json(404, {"error": "short code not found"})
                return
            self._send_json(200, stats)

        def _handle_update(self, code):
            body = self._read_json()
            result = service.update_url(
                code, self._api_key(), long_url=body.get("long_url"), expires_at=body.get("expires_at")
            )
            self._send_json(200, result)

        def _handle_delete(self, code):
            result = service.delete_url(code, self._api_key())
            self._send_json(200, result)

    return Handler
